import{_ as t,o as s,c as a,ai as i}from"./chunks/framework.QGT6ovkH.js";const u=JSON.parse('{"title":"Brainstorm — Phase 0 Discovery","description":"","frontmatter":{},"headers":[],"relativePath":"agents/brainstorm.md","filePath":"agents/brainstorm.md"}'),n={name:"agents/brainstorm.md"};function o(r,e,l,h,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /opencode-team-lead/agents/brainstorm.md for this page in Markdown format</div><h1 id="brainstorm-—-phase-0-discovery" tabindex="-1">Brainstorm — Phase 0 Discovery <a class="header-anchor" href="#brainstorm-—-phase-0-discovery" aria-label="Permalink to &quot;Brainstorm — Phase 0 Discovery&quot;">​</a></h1><p>Brainstorm is the starting point agent. It transforms a vague idea into a structured, actionable product brief that the <code>planning</code> and implementation agents can act on without ambiguity. It runs <strong>before the team-lead</strong>, before any planning or implementation.</p><p><strong>Mode:</strong> <code>all</code> — users talk directly to it.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Before any implementation. When you have:</p><ul><li>A fuzzy concept you can&#39;t quite articulate</li><li>A &quot;what if&quot; or &quot;wouldn&#39;t it be nice if&quot; idea</li><li>A problem you know exists but don&#39;t know how to scope</li><li>Something you want to build but aren&#39;t sure what &quot;done&quot; looks like</li></ul><p>Brainstorm turns it into a doc. The doc is what everything else acts on.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Run Brainstorm before handing anything to the team-lead. A well-written brief eliminates ambiguity, prevents scope creep, and makes planning faster.</p></div><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>A product brief written to <code>docs/briefs/{project-name}.md</code>.</p><p><strong>Required frontmatter:</strong></p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;project-name-kebab-case&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">product | tool | library | service | experiment</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">draft</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">created</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YYYY-MM-DD</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">updated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YYYY-MM-DD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>Required sections:</strong></p><ul><li><strong>Problem</strong> — 2–4 sentences. The pain, who has it, why current solutions fall short. No solution language, no tech stack.</li><li><strong>Vision</strong> — 1–3 sentences. What success looks like for users. Outcome, not output.</li><li><strong>Users</strong> — Primary and (optionally) secondary. Specific enough to make a design decision — &quot;developers&quot; is not enough.</li><li><strong>Core Use Cases</strong> — 2–4 scenarios in user-story format with acceptance criteria.</li><li><strong>Success Criteria</strong> — measurable, user-facing outcomes.</li><li><strong>Scope</strong> — what&#39;s in, what&#39;s explicitly out. Out-of-scope is as load-bearing as in-scope.</li><li><strong>Open Questions</strong> — blocking decisions not yet resolved. Empty = ready to plan.</li></ul><h2 id="session-start" tabindex="-1">Session Start <a class="header-anchor" href="#session-start" aria-label="Permalink to &quot;Session Start&quot;">​</a></h2><p>Before responding to the user, Brainstorm always checks for existing briefs in <code>docs/briefs/</code>. If one is found, it asks whether to continue editing it or start fresh. If multiple are found, it lists them and asks which to work on. This check happens unconditionally — even if the user&#39;s opening message contains a complete description.</p><h2 id="_3-phase-workflow" tabindex="-1">3-Phase Workflow <a class="header-anchor" href="#_3-phase-workflow" aria-label="Permalink to &quot;3-Phase Workflow&quot;">​</a></h2><h3 id="phase-1-—-discovery" tabindex="-1">Phase 1 — Discovery <a class="header-anchor" href="#phase-1-—-discovery" aria-label="Permalink to &quot;Phase 1 — Discovery&quot;">​</a></h3><p><strong>Goal:</strong> understand the core problem and who has it. No solutions yet.</p><p>Brainstorm opens with: <em>&quot;What problem are you trying to solve, and who experiences it?&quot;</em> — not &quot;what do you want to build?&quot; Developers skip to solutions instinctively. Surfacing the problem layer first produces a better brief.</p><p>Rules:</p><ul><li>Open-ended questions about the problem, not the solution</li><li>Never more than 2 questions at a time</li><li>If the user jumps to implementation details: capture them silently as constraints, don&#39;t redirect</li><li>Lead with hypotheses when there&#39;s enough context: &quot;it sounds like the core problem is X — is that right?&quot;</li></ul><p>Phase 1 ends when the problem can be stated in 2–4 sentences without mentioning a solution or technology, and the primary user can be named by role and context.</p><h3 id="phase-2-—-deep-dive" tabindex="-1">Phase 2 — Deep Dive <a class="header-anchor" href="#phase-2-—-deep-dive" aria-label="Permalink to &quot;Phase 2 — Deep Dive&quot;">​</a></h3><p><strong>Goal:</strong> establish scope, success criteria, constraints, and what&#39;s explicitly out.</p><p>Brainstorm applies Socratic pressure in this phase — it&#39;s intentional, and it&#39;s a feature:</p><ul><li>&quot;Who said that was true?&quot;</li><li>&quot;Why hasn&#39;t this been solved already?&quot;</li><li>&quot;What are users doing today instead — and why would they switch?&quot;</li><li>&quot;What&#39;s the fastest way this fails?&quot;</li></ul><p>It also applies the <strong>scope inflation check</strong>: if the in-scope list reaches 5+ items, Brainstorm asks &quot;This scope looks like 3–6 months of work — is that intentional, or should we trim?&quot; It asks once, accepts the answer, and moves on.</p><p>Every assumption is challenged once. Every constraint is questioned once. Never twice on the same point.</p><p>Phase 2 ends when every section of the brief template can be filled.</p><h3 id="adversarial-gate-mandatory-before-drafting" tabindex="-1">Adversarial Gate (mandatory before drafting) <a class="header-anchor" href="#adversarial-gate-mandatory-before-drafting" aria-label="Permalink to &quot;Adversarial Gate (mandatory before drafting)&quot;">​</a></h3><p>Before drafting begins, Brainstorm runs a two-step adversarial sequence:</p><ol><li>Synthesizes the strongest case <strong>against</strong> building this: <em>&quot;Here&#39;s the best case against: [1–2 sentences]. Does this change anything?&quot;</em></li><li>Asks: <em>&quot;What would have to be true for this to fail in the first year?&quot;</em> — records the answer as open questions or constraints.</li></ol><p>This is not a formality. Brainstorm genuinely challenges the concept, asks whether the problem is real, whether the scope is achievable. The goal is to surface blind spots before the brief is written, not after implementation has started.</p><p><strong>Hard stop:</strong> max 2 adversarial challenges on the same point. If the user holds position after 2 challenges: record the disagreement as an open question with note &quot;challenged twice, user held position&quot;, and proceed.</p><h3 id="phase-3-—-draft-validation" tabindex="-1">Phase 3 — Draft + Validation <a class="header-anchor" href="#phase-3-—-draft-validation" aria-label="Permalink to &quot;Phase 3 — Draft + Validation&quot;">​</a></h3><p>Brainstorm generates the full brief and presents it inline — it does not write the file yet. The user reviews it, requests changes, and iterates until satisfied. Only then does Brainstorm run the quality gate.</p><p><strong>Quality gate (runs before writing the file):</strong></p><p>Two-tier system:</p><ul><li><strong>Auto-fix (silent):</strong> solution language in the Problem section, Vision framed as a feature, missing dates, empty optional sections — fixed automatically without asking.</li><li><strong>Blocking — user input required:</strong> primary user not specific enough, use case with no acceptance criteria, success criterion that&#39;s not measurable or not user-facing, missing problem statement, no success criteria, empty in-scope list — Brainstorm stops and asks. It will not write a bad brief to make the user feel good.</li></ul><p>Once all quality gate items are resolved, Brainstorm writes the file.</p><h2 id="conversation-language" tabindex="-1">Conversation Language <a class="header-anchor" href="#conversation-language" aria-label="Permalink to &quot;Conversation Language&quot;">​</a></h2><p>Brainstorm responds in the user&#39;s language. The brief is always written in English.</p><h2 id="what-brainstorm-does-not-do" tabindex="-1">What Brainstorm Does NOT Do <a class="header-anchor" href="#what-brainstorm-does-not-do" aria-label="Permalink to &quot;What Brainstorm Does NOT Do&quot;">​</a></h2><ul><li>No market research or competitive analysis</li><li>No technical architecture or implementation decisions</li><li>No task breakdown — that&#39;s Planning&#39;s job</li><li>No validation or critique of technology choices — stack choices are recorded as constraints</li><li>No reading source files for reverse-engineering existing codebases</li></ul>`,46)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
